ipcMain.handle('api-set', (e, { provider, key, model } = {}) => {
  if (!PROVIDERS[provider]) return false;
  PREFS.apiKeys = PREFS.apiKeys || {};
  const { safeStorage } = require('electron');
  const encrypted = safeStorage.isEncryptionAvailable();
  if (key && !encrypted) {
    return { ok: false, error: LANG === 'en'
      ? 'OS secure storage unavailable — the key was NOT saved (plaintext storage disabled).'
      : "Stockage sécurisé indisponible — la clé n'a PAS été enregistrée (stockage en clair désactivé)." };
  }
  if (key) {
    PREFS.apiKeys[provider] = safeStorage.encryptString(key).toString('base64');
    PREFS.apiEncrypted = PREFS.apiEncrypted || {};
    PREFS.apiEncrypted[provider] = true;
  } else {
    delete PREFS.apiKeys[provider];
    if (PREFS.apiEncrypted) delete PREFS.apiEncrypted[provider];
  }
  // …model handling unchanged…
});

function writeItemMd(it, dir) {
  const base = path.resolve(dir || promptDir());
  const abs = path.resolve(base, itemRelPath(it));
  if (abs !== base && !abs.startsWith(base + path.sep)) {
    throw new Error('write escaped promptDir: ' + itemRelPath(it));
  }
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, mdForItem(it), 'utf8');
  return abs;
}

// mdSafe: reject dot-only segments outright
const mdSafe = (s) => {
  const out = String(s || '').replace(/[/\\:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 80);
  return (out && out !== '.' && out !== '..') ? out : 'sans-nom';
};
